import java.util.*;
public class ManualEqualityStepsDemo {
  public static void main(String[] args) {
    class Key { final String id; final int srid; Key(String i,int s){id=i;srid=s;} public boolean equals(Object o){if(this==o)return true; if(!(o instanceof Key k))return false; return srid==k.srid && java.util.Objects.equals(id,k.id);} public int hashCode(){return java.util.Objects.hash(id,srid);} }
    var a=new Key("P1",32614); var b=new Key("P1",32614); System.out.println(a.equals(b)+" "+(a.hashCode()==b.hashCode()));
  }
}
